window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[283]={"id":"283","numero":283,"titre":"Constipation chez l'enfant et l'adulte","objectifs":[{"id":"283-1","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence de la constipation chez l’enfant","contenu":"<p>La <span class=\"kw-clinique\">constipation</span> est l'un des <span class=\"kw-def\">motifs les plus fréquents de consultation en pédiatrie</span>. Sa <span class=\"kw-def\">prévalence</span> chez l'enfant est estimée à <span class=\"kw-chiffre\">environ 10 %</span> (larges variations selon <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">critères diagnostiques</span> retenus).</p>\n      <p><span class=\"kw-clinique\">Les</span> pics de survenue correspondent à <span class=\"kw-chiffre\">trois étapes clés</span> du développement :</p>\n      <ul>\n        <li>la <span class=\"kw-clinique\">diversification alimentaire</span> (passage à l'alimentation solide) ;</li>\n        <li>l'<span class=\"kw-clinique\">apprentissage de la propreté</span> (rétention volontaire au moment du contrôle sphinctérien) ;</li>\n        <li>l'<span class=\"kw-clinique\">entrée à l'école</span> (refus des toilettes scolaires, rétention prolongée).</li>\n      </ul>\n      <p><strong>Point capital pour le raisonnement :</strong> chez l'enfant, la <span class=\"kw-clinique\">constipation</span> est <span class=\"kw-chiffre\">fonctionnelle dans ~95 % des cas</span>. <span class=\"kw-clinique\">Les</span> causes <span class=\"kw-etio\">organiques</span> et <span class=\"kw-etio\">congénitales</span> sont rares (<span class=\"kw-chiffre\">&lt; 5 %</span>), mais ce sont elles qu'il ne faut pas manquer (cf. objectif <span class=\"kw-def\">Physiopathologie</span>).</p>\n      <p>Pour mémoire, dans la population <strong>adulte</strong>, la <span class=\"kw-def\">prévalence</span> est de <span class=\"kw-chiffre\">15 à 20 %</span>, avec une <span class=\"kw-clinique\">prédominance féminine</span> nette — rôle des <span class=\"kw-def\">hormones sexuelles</span> (la <span class=\"kw-def\">progestérone</span> ralentit le transit) et conséquences mécaniques de l'<span class=\"kw-clinique\">accouchement</span> sur la statique pelvienne.</p>","frequence":0},{"id":"283-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la constipation chronique","contenu":"<p>La <span class=\"kw-clinique\">constipation</span> se définit par <strong>l'un OU l'autre</strong> des deux critères suivants :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Moins de <span class=\"kw-chiffre\">3 selles par semaine</span></span> ;</li>\n        <li>OU une <strong>difficulté d'exonération</strong> — la <span class=\"kw-clinique\">dyschésie</span> : efforts de <span class=\"kw-clinique\">poussée</span> exagérés, sensation de gêne, évacuation incomplète, temps d'exonération anormalement prolongé, nécessité de <strong>manœuvres digitales</strong> (endovaginale, endoanale, massage périnéal).</li>\n      </ul>\n      <table >\n        <thead><tr><th>Notion</th><th>Précision</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Condition indispensable</strong></td><td>La <span class=\"kw-clinique\">constipation</span> n'est retenue que s'il existe une <strong>plainte du patient</strong> sur son transit</td></tr>\n          <tr><td><strong>Selles liquides</strong></td><td>N'éliminent <strong>pas</strong> une <span class=\"kw-clinique\">constipation</span> — en particulier si elles précèdent ou suivent une période sans évacuation : <span class=\"kw-alerte\">fausse diarrhée</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Constipation</span> chronique</strong></td><td><span class=\"kw-clinique\">Évolution</span> <span class=\"kw-chiffre\">&gt; 6 mois</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Constipation</span> occasionnelle</strong></td><td>Entité à part : apparition assez brutale dans des circonstances particulières (derniers mois de <span class=\"kw-ci\">grossesse</span>, alitement, voyage)</td></tr>\n        </tbody>\n      </table>\n      <p>Cliniquement : <span class=\"kw-clinique\">sensibilité de la fosse iliaque gauche</span> (en regard du côlon gauche et du s<span class=\"kw-chiffre\">igm</span>oïde où sont stockées <span class=\"kw-clinique\">les</span> matières fécales) et <span class=\"kw-clinique\">météorisme abdominal</span> possible. L'<span class=\"kw-def\">échelle de Bristol</span> apprécie la forme et la consistance des selles : un <span class=\"kw-def\">score</span> <span class=\"kw-chiffre\">Bristol 1 ou 2</span> traduit une <span class=\"kw-clinique\">constipation</span>.</p>\n      <div class=\"callout callout-info\"><strong>Spécificité enfant — <span class=\"kw-def\">critères de</span> <span class=\"kw-def\">Rome IV</span>.</strong> Chez l'enfant, la <span class=\"kw-clinique\">constipation</span> a sa propre définition, distincte de l'adulte. Critères pédiatriques officiels :</div>\n      <table >\n        <thead><tr><th>Tranche d'âge</th><th>Critères Rome IV</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Avant <span class=\"kw-chiffre\">4 ans</span></strong><br>(≥ <span class=\"kw-chiffre\">2 critères depuis 1 mois</span>)</td>\n            <td>\n              <span class=\"kw-clinique\">&lt; 2 selles / semaine</span> ; <span class=\"kw-clinique\">rétention fécale excessive</span> ; <span class=\"kw-clinique\">exonération douloureuse ou difficile</span> ; <span class=\"kw-clinique\">selles de gros calibre</span> ; <span class=\"kw-clinique\">fécalome au toucher rectal</span><br>\n              <em>Après acquisition de la propreté :</em> <span class=\"kw-clinique\">≥ 1 épisode d'incontinence / semaine</span> ; <span class=\"kw-clinique\">selles de gros calibre pouvant obstruer les toilettes</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Après <span class=\"kw-chiffre\">4 ans</span></strong><br>(≥ <span class=\"kw-chiffre\">2 critères ≥ 1×/sem depuis 1 mois</span>, en l'absence de SII)</td>\n            <td><span class=\"kw-clinique\">&lt; 2 selles / semaine</span> ; <span class=\"kw-clinique\">≥ 1 épisode d'incontinence / semaine</span> ; <span class=\"kw-clinique\">posture de rétention ou rétention délibérée</span> ; <span class=\"kw-clinique\">exonération douloureuse ou difficile</span> ; <span class=\"kw-clinique\">fécalome au toucher rectal</span> ; <span class=\"kw-clinique\">selles de gros calibre</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Repères pédiatriques utiles : le contrôle actif de l'exonération s'acquiert entre <span class=\"kw-chiffre\">2 et 4 ans</span>. Chez le <span class=\"kw-clinique\">nourrisson allaité</span>, un intervalle entre selles <span class=\"kw-chiffre\">&gt; 1 semaine</span> peut être <strong>physiologique</strong> (« <span class=\"kw-clinique\">constipation</span> au lait de mère ») et ne justifie aucun traitement.</p>","frequence":1},{"id":"283-3","rang":"B","rubrique":"Physiopathologie","titre":"Distinguer l’origine fonctionnelle de l’origine organique et surtout congénitale de la constipation chez l’enfant","contenu":"<p>La <span class=\"kw-clinique\">constipation</span> idiopathique (« <span class=\"kw-clinique\">constipation</span> maladie ») relève de <strong>2 mécanismes pouvant coexister</strong>, à distinguer de l'origine <span class=\"kw-etio\">organique</span> (<span class=\"kw-clinique\">constipation</span> « symptôme », cf. objectif Étiologies) et de l'origine <span class=\"kw-etio\">congénitale</span> de l'enfant.</p>\n      <p>Chez l'enfant, ce raisonnement obéit à une règle simple : la <span class=\"kw-clinique\">constipation</span> est <span class=\"kw-chiffre\">fonctionnelle dans ~95 % des cas</span> — l'origine organique ou <span class=\"kw-etio\">congénitale</span> reste l'exception, mais c'est elle qu'il ne faut pas méconnaître.</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th><span class=\"kw-clinique\">Constipation</span> de transit</th><th><span class=\"kw-clinique\">Constipation</span> distale (dyschésie)</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Définition</strong></td><td><span class=\"kw-def\">Ralentissement du transit colique</span></td><td><span class=\"kw-def\">Trouble de l'évacuation rectale</span></td></tr>\n          <tr><td><strong>Clinique</strong></td><td><span class=\"kw-clinique\">Nombre de selles diminué</span> ; selles déshydratées, petites et dures (séjour prolongé dans le côlon)</td><td><span class=\"kw-clinique\">Nombre de selles normal</span> ; effort de <span class=\"kw-clinique\">poussée</span> exagéré, voire manœuvres digitales</td></tr>\n          <tr><td><strong>Explorations</strong></td><td>Temps de transit augmenté (marqueurs stagnant dans le côlon) ; <span class=\"kw-clinique\">manométrie anorectale normale</span></td><td>Temps de transit normal ou ralenti (marqueurs stagnant au niveau recto-s<span class=\"kw-chiffre\">igm</span>oïdien)</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-clinique\">Les</span> 2 mécanismes de la <span class=\"kw-clinique\">constipation</span> de transit :</strong></p>\n      <ul>\n        <li><span class=\"kw-def\">Hypomotricité (côlon atone) :</span> diminution de l'amplitude et de la fréquence des contractions coliques de grande amplitude (mouvements de <span class=\"kw-clinique\">masse</span>).</li>\n        <li><span class=\"kw-def\">Hyperactivité segmentaire :</span> augmentation des contractions segmentaires s<span class=\"kw-chiffre\">igm</span>oïdiennes freinant la progression des selles — souvent marquée par une <span class=\"kw-clinique\">douleur abdominale</span> : <span class=\"kw-etio\">SII avec constipation</span>.</li>\n      </ul>\n      <p><strong><span class=\"kw-clinique\">Les</span> 3 causes de la <span class=\"kw-clinique\">constipation</span> distale :</strong></p>\n      <ul>\n        <li><span class=\"kw-def\">Dyssynergie anorectale :</span> défaut d'ouverture du canal anal lors de la <span class=\"kw-clinique\">poussée</span> (défaut de relaxation, voire contraction paradoxale du sphincter anal externe).</li>\n        <li><span class=\"kw-def\">Troubles de la statique pelvienne postérieure :</span> rectocèle (hernie de la cloison rectovaginale), syndrome du périnée descendant, procidence rectale interne (intussusception).</li>\n        <li><span class=\"kw-def\">Hyposensibilité rectale :</span> atténue ou supprime la sensation de besoin exonérateur — cause fréquente chez le sujet âgé (<span class=\"kw-clinique\">syndrome de la</span> queue de cheval, mégarectum).</li>\n      </ul>\n      <p><strong>Facteurs favorisants</strong> de la <span class=\"kw-clinique\">constipation</span> de transit : <span class=\"kw-clinique\">manque d'activité physique</span>, <span class=\"kw-clinique\">déficit en fibres alimentaires</span>, facteurs psychologiques (notamment antécédent d'abus sexuel ou physique).</p>\n      <p><strong>Origine <span class=\"kw-etio\">congénitale</span> — la maladie de Hirschsprung</strong> (à distinguer) : c'est la principale cause congénitale à évoquer devant une <span class=\"kw-clinique\">constipation</span> de l'enfant.</p>\n      <table >\n        <thead><tr><th>Item</th><th>Maladie de Hirschsprung</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Mécanisme</strong></td><td><span class=\"kw-def\">Aganglionose colique congénitale</span> : absence de cellules ganglionnaires des <span class=\"kw-def\">plexus de Meissner (sous-muqueux)</span> et <span class=\"kw-def\">d'Auerbach (myentérique)</span> sur un segment distal du côlon → segment atone, non propulsif et spastique</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Prévalence</span> / <span class=\"kw-def\">terrain</span></strong></td><td><span class=\"kw-chiffre\">1 nouveau-né sur 5 000</span> ; association fréquente avec la <span class=\"kw-etio\">trisomie 21</span> — présente dans <span class=\"kw-chiffre\">~ 1 % des T21</span></td></tr>\n          <tr><td><strong>Clinique évocatrice</strong></td><td><span class=\"kw-alerte\">Retard à l'émission du méconium &gt; 24-48 h</span> ; <span class=\"kw-clinique\">constipation</span> présente <strong>dès la naissance</strong> ; ballonnement abdominal. <strong>TR (3 signes ⭐) :</strong> <span class=\"kw-clinique\">ampoule rectale vide</span>, <span class=\"kw-clinique\">hypertonie du sphincter anal</span>, <span class=\"kw-clinique\">débâcle de selles fétides et de gaz nauséabonds au retrait du doigt</span></td></tr>\n          <tr><td><strong>Diagnostic</strong></td><td><span class=\"kw-imagerie\">Manométrie anorectale</span> : <span class=\"kw-def\">absence du réflexe recto-anal inhibiteur</span> ; <span class=\"kw-imagerie\">lavement opaque</span> : disparité de calibre avec stagnation du PDC dans la zone sus-jacente dilatée ; confirmation par <span class=\"kw-imagerie\">biopsies rectales</span> montrant l'<span class=\"kw-def\">aganglionose avec hyperplasie schwannienne</span></td></tr>\n          <tr><td><strong>Traitement</strong></td><td><span class=\"kw-ttt\">Chirurgical</span> : <strong><span class=\"kw-ttt\">exérèse</span> du segment apéristaltique</strong></td></tr>\n        </tbody>\n      </table>","frequence":2},{"id":"283-4","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’indication des examens d’imagerie devant une constipation","contenu":"<p>Principe directeur : <span class=\"kw-alerte\">aucun examen n'est systématique en l'absence de signe d'alarme</span>. Le bilan est guidé par le contexte clinique et par la recherche d'une cause secondaire.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Biologie</span></td><td><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">créatininémie</span>, <span class=\"kw-bio\">glycémie</span>, <span class=\"kw-bio\">calcémie</span>, <span class=\"kw-bio\">TSH</span> — non systématique, selon le contexte clinique</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Coloscopie</span> (sous AG)</td><td>Âge d'apparition <span class=\"kw-chiffre\">&gt; 50 ans</span> ; signe d'alarme (<span class=\"kw-alerte\">rectorragie</span>, <span class=\"kw-alerte\">AEG</span>, <span class=\"kw-alerte\">anémie</span>, modification récente et inexpliquée du transit) ; situation où le <span class=\"kw-def\">dépistage</span> du cancer colorectal est recommandé (ex. ATCD familial de 1ᵉʳ degré de cancer colique)</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Coloscanner</span></td><td>Réservé aux <span class=\"kw-ci\">contre-indications</span> de la <span class=\"kw-imagerie\">coloscopie</span>, ou si <span class=\"kw-imagerie\">coloscopie</span> incomplète</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Temps de transit aux marqueurs</span></td><td>2ᵉ intention, si échec des traitements conservateurs : <span class=\"kw-imagerie\">ASP</span> après ingestion de marqueurs radio-opaques ; temps de transit colique normal <span class=\"kw-chiffre\">≈ 60 h</span> ; à réaliser <strong>après arrêt des laxatifs</strong>. <span class=\"kw-alerte\">Sensibilité faible</span>, grande variabilité inter- et intra-individuelle ; un transit <strong>normal</strong> oriente soit vers une <span class=\"kw-etio\">fausse constipation</span>, soit vers une <span class=\"kw-etio\">constipation distale</span> n'ayant pas encore retenti sur le transit colique</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Manométrie anorectale</span></td><td>2ᵉ intention : identifie un trouble fonctionnel de l'exonération (<span class=\"kw-clinique\">dyssynergie anorectale</span> = absence de relaxation, voire contraction paradoxale du sphincter à la <span class=\"kw-clinique\">poussée</span>)</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Défécographie</span> / <span class=\"kw-imagerie\">déféco-IRM</span></td><td>Examen morphologique 2ᵉ intention, si échec des traitements et si une <strong><span class=\"kw-ttt\">chirurgie</span> est envisagée</strong> : recherche un trouble de la statique pelvienne</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Lavement opaque</span></td><td>Indication pédiatrique en cas de suspicion de <span class=\"kw-etio\">maladie de Hirschsprung</span> : montre une <span class=\"kw-radio\">disparité de calibre</span> avec stagnation du produit de contraste dans la zone sus-jacente dilatée</td></tr>\n        </tbody>\n      </table>\n      <p><span class=\"kw-clinique\">Les</span> examens fonctionnels et morphologiques explorent une <strong><span class=\"kw-clinique\">constipation</span> idiopathique</strong> ; ils ne sont demandés qu'<span class=\"kw-chiffre\">après échec</span> des traitements conservateurs, en l'absence de cause identifiable.</p>\n      <div class=\"callout callout-info\"><strong>Spécificité enfant — règle plus stricte qu'adulte.</strong> <span class=\"kw-alerte\">Aucun examen complémentaire n'est justifié en cas de constipation fonctionnelle</span> de l'enfant. L'<span class=\"kw-imagerie\">ASP</span> n'a <span class=\"kw-alerte\">pas d'intérêt diagnostique</span> dans cette indication (ni dans le <span class=\"kw-def\">suivi</span>) ; il n'est utile que devant un <span class=\"kw-alerte\">syndrome occlusif</span> de l'enfant. <span class=\"kw-clinique\">Les</span> examens d'imagerie sont réservés aux situations évoquant une cause organique ou <span class=\"kw-etio\">congénitale</span> (<span class=\"kw-alerte\">signes d'alarme</span>, échec thérapeutique, début néonatal).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 301 — Tumeur colon - rectum · 354 — Syndrome occlusif</em></p>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/double-contrast-barium-enema-technique","label":"Radiopaedia : Double contrast barium enema technique"},{"href":"https://radiopaedia.org/articles/mr-defaecating-proctography-1","label":"Radiopaedia : Mr defaecating proctography 1"}]},{"id":"283-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les caractéristiques cliniques et les éléments de diagnostic différentiel","contenu":"<p><strong>Caractéristiques cliniques.</strong> Le diagnostic est avant tout <span class=\"kw-def\">clinique</span> et associe la <span class=\"kw-def\">définition</span> (<span class=\"kw-chiffre\">&lt; 3 selles/semaine</span> ou <span class=\"kw-clinique\">dyschésie</span>) à une <span class=\"kw-clinique\">plainte du patient</span>. L'examen retrouve volontiers une <span class=\"kw-clinique\">sensibilité de la fosse iliaque gauche</span>, en regard du côlon gauche et du s<span class=\"kw-chiffre\">igm</span>oïde où sont stockées <span class=\"kw-clinique\">les</span> matières fécales, et un <span class=\"kw-clinique\">météorisme abdominal</span> possible. L'<span class=\"kw-def\">échelle de Bristol</span> (<span class=\"kw-def\">score</span> <span class=\"kw-chiffre\">1 ou 2</span>) objective la consistance.</p>\n      <p>Chez l'enfant, le <span class=\"kw-clinique\">toucher rectal</span> reste un temps d'examen essentiel : il recherche un <span class=\"kw-alerte\">fécalome</span>, apprécie le tonus sphinctérien et la vacuité de l'ampoule (signes orientant vers une <span class=\"kw-etio\">cause organique</span>, en particulier <span class=\"kw-etio\">Hirschsprung</span>).</p>\n      <p><strong><span class=\"kw-def\">Diagnostic différentiel</span>.</strong></p>\n      <table >\n        <thead><tr><th>Entité</th><th>Élément distinctif</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Fausse diarrhée</span></td><td>Émission de <span class=\"kw-clinique\">selles liquides</span> précédant ou suivant une période sans évacuation — il s'agit en réalité d'une <span class=\"kw-clinique\">constipation</span>, à ne pas méconnaître</td></tr>\n          <tr><td><span class=\"kw-etio\">SII avec constipation</span></td><td><span class=\"kw-clinique\">Constipation</span> associée à une <span class=\"kw-clinique\">douleur abdominale</span> au premier plan (hyperactivité segmentaire s<span class=\"kw-chiffre\">igm</span>oïdienne)</td></tr>\n          <tr><td><span class=\"kw-etio\">Diarrhée chronique vraie</span></td><td>Selles authentiquement trop fréquentes / trop liquides, sans période de rétention — situation opposée à la <span class=\"kw-clinique\">constipation</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 284 — <span class=\"kw-clinique\">Syndrome de l</span>’intestin irritable (SII) · 285 — <span class=\"kw-clinique\">Diarrhée</span> chronique</em></p>","frequence":0},{"id":"283-6","rang":"B","rubrique":"Étiologies","titre":"Distinguer la constipation fonctionnelle des causes organiques et congénitales","contenu":"<p>Distinguer la <strong><span class=\"kw-clinique\">constipation</span> fonctionnelle</strong> (idiopathique, « maladie ») des <strong>causes organiques et congénitales</strong> (<span class=\"kw-clinique\">constipation</span> « symptôme ») repose d'abord sur la recherche de <span class=\"kw-alerte\">signes d'alarme</span>.</p>\n      <table >\n        <thead><tr><th>Signes d'alarme</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Cliniques</strong></td><td><span class=\"kw-alerte\">AEG</span>, <span class=\"kw-clinique\">amaigrissement</span> ; douleurs nocturnes et insomniantes ; <span class=\"kw-alerte\">rectorragies</span>, <span class=\"kw-clinique\">méléna</span> ; syndrome rectal (épreintes, ténesme, faux besoins) ; <span class=\"kw-clinique\">masse</span> abdominale ou rectale ; <span class=\"kw-clinique\">constipation</span> sévère résistante au traitement ou s'aggravant sans cause évidente</td></tr>\n          <tr><td><strong>Biologiques</strong></td><td><span class=\"kw-bio\">Anémie</span> ; <span class=\"kw-def\">syndrome inflammatoire</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Causes secondaires de <span class=\"kw-clinique\">constipation</span> :</strong></p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Médicaments</span></td><td><span class=\"kw-ttt\">Opiacés</span> +++ ; <span class=\"kw-ttt\">anticholinergiques</span> ; <span class=\"kw-ttt\">antidépresseurs</span> ; <span class=\"kw-ttt\">antipsychotiques</span> ; <span class=\"kw-ttt\">antiparkinsoniens</span> ; <span class=\"kw-ttt\">fer</span> ; <span class=\"kw-ttt\">carbamazépine</span> ; <span class=\"kw-ttt\">vincristine</span> ; <span class=\"kw-ttt\">furosémide</span> (hypokaliémiant) ; <span class=\"kw-ttt\">colestyramine</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Obstruction mécanique</span></td><td><strong>Luminale :</strong> cancer colorectal ou de l'intestin grêle ;<br><strong>Sténoses non tumorales :</strong> diverticulaire, <span class=\"kw-etio\">inflammatoire</span>, <span class=\"kw-etio\">ischémique</span> ; sténose anale (cancer du canal anal, sténose cicatricielle) ;<br><strong>Compression extrinsèque :</strong> tumeur, carcinose péritonéale, adhérences post-chirurgicales, endométriose, prolapsus</td></tr>\n          <tr><td><span class=\"kw-etio\">Métaboliques</span></td><td><strong>Troubles ioniques :</strong> <span class=\"kw-bio\">hypercalcémie</span>, <span class=\"kw-bio\">hypocalcémie</span>, <span class=\"kw-bio\">hypomagnésémie</span>, <span class=\"kw-bio\">hypokaliémie</span> ;<br><strong>Endocriniennes / rénales :</strong> <span class=\"kw-etio\">hypothyroïdie</span>, <span class=\"kw-etio\">diabète</span>, <span class=\"kw-ci\">insuffisance rénale</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Systémiques</span></td><td><span class=\"kw-etio\">Amylose</span> ; <span class=\"kw-etio\">sclérodermie</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Neurologiques</span></td><td>Près de <span class=\"kw-chiffre\">50 %</span> des patients atteints de maladie neurologique chronique ont des troubles du transit : <span class=\"kw-etio\">maladie de Parkinson</span>, tumeur / traumatisme médullaire, <span class=\"kw-clinique\">syndrome de la</span> queue de cheval, <span class=\"kw-etio\">AVC</span>, SEP, <span class=\"kw-clinique\">syndrome de Shy</span>-Drager</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Causes congénitales.</strong> Chez l'enfant, la cause <span class=\"kw-etio\">congénitale</span> de référence est la <strong>maladie de Hirschsprung</strong> (<span class=\"kw-def\">aganglionose colique congénitale</span>) — détaillée dans l'objectif <span class=\"kw-def\">Physiopathologie</span>. À évoquer systématiquement devant une <span class=\"kw-clinique\">constipation</span> néonatale ou un <span class=\"kw-alerte\">retard d'émission du méconium</span>.</p>\n      <div class=\"callout callout-info\"><strong>Spécificités pédiatriques — causes organiques (&lt; <span class=\"kw-chiffre\">5 %</span> des étiologies).</strong> À évoquer si <span class=\"kw-alerte\">signes d'alarme</span> ou résistance au traitement.</div>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Étiologies pédiatriques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Causes médicales</span></td><td><span class=\"kw-etio\">Hypothyroïdie</span> ; <span class=\"kw-etio\">maladie cœliaque</span> (rare) ; <span class=\"kw-etio\">diabète insipide</span> ; <span class=\"kw-bio\">hypercalcémie</span> ; <span class=\"kw-etio\">anorexie mentale</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Anomalies neuromusculaires</span></td><td><span class=\"kw-etio\">Maladie de Hirschsprung</span> ; <span class=\"kw-etio\">pseudo-obstruction intestinale chronique (POIC)</span> ; <span class=\"kw-etio\">encéphalopathie</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Obstacles anatomiques</span></td><td><span class=\"kw-etio\">Malformations anorectales</span> hautes ou basses ; <span class=\"kw-etio\">sténoses</span> congénitales ou acquises</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Distinguer fonctionnel <span class=\"kw-bio\">vs</span> organique chez l'enfant — tableau d'orientation :</strong></p>\n      <table >\n        <thead><tr><th>Élément</th><th>En faveur d'une cause <span class=\"kw-etio\">fonctionnelle</span></th><th>En faveur d'une cause <span class=\"kw-etio\">organique</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span> / contexte</strong></td>\n            <td>Prise médicamenteuse (<span class=\"kw-ttt\">morphine</span>) ; ATCD familiaux de <span class=\"kw-clinique\">constipation</span> fonctionnelle ; période d'acquisition de la propreté ; handicap / inactivité ; toilettes inadaptées ; régime à <span class=\"kw-clinique\">faible résidu</span></td>\n            <td>Début <span class=\"kw-alerte\">néonatal</span> ; <span class=\"kw-alerte\">retard d'émission du méconium &gt; 48 h</span> ; <span class=\"kw-alerte\">échec d'un traitement symptomatique</span> bien conduit</td>\n          </tr>\n          <tr>\n            <td><strong>Présentation clinique</strong></td>\n            <td>Gêne mécanique / <span class=\"kw-clinique\">douleur anale à l'exonération</span> ; <span class=\"kw-clinique\">attitude de rétention</span> à l'école ; <span class=\"kw-alerte\">encoprésie</span> (&gt;<span class=\"kw-chiffre\"> 4 ans</span>)</td>\n            <td><span class=\"kw-alerte\">Cassure staturo-pondérale</span> ; <span class=\"kw-clinique\">météorisme important</span> (peut aussi être fonctionnel) ; <span class=\"kw-alerte\">épisodes subocclusifs</span>, <span class=\"kw-clinique\">vomissements</span> ; <span class=\"kw-clinique\">anomalies de la marge anale, du périnée ou de la région sacrée</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 301 — Tumeur colon - rectum · 354 — Syndrome occlusif · 287 — Diverticulose colique - <span class=\"kw-clinique\">diverticulite</span> aiguë · 268 — Hypercalcémie · 243 — <span class=\"kw-etio\">Hypothyroïdie</span> · 106 — Parkinson · 93 — Compression médullaire non trauma</em></p>","frequence":0},{"id":"283-7","rang":"A","rubrique":"Prise en charge","titre":"Connaître les règles hygiénodiététiques","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">règles hygiénodiététiques</span> constituent le <strong>socle</strong> de la prise en charge de la <span class=\"kw-clinique\">constipation</span> idiopathique, en <span class=\"kw-chiffre\">1ʳᵉ ligne</span> avant tout traitement <span class=\"kw-etio\">médicamenteux</span>.</p>\n      <p><strong>Chez l'adulte :</strong></p>\n      <table >\n        <thead><tr><th>Mesure</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Régime enrichi en fibres</span></td><td>Environ <span class=\"kw-chiffre\">25 g/jour</span> : <span class=\"kw-ttt\">fruits, légumes, céréales</span> — augmentent la fréquence des selles, améliorent leur consistance et diminuent la consommation de laxatifs</td></tr>\n          <tr><td><span class=\"kw-clinique\">Eaux riches en magnésium</span></td><td>Peuvent être recommandées</td></tr>\n          <tr><td><span class=\"kw-clinique\">Présentation régulière aux toilettes</span></td><td>Pour exploiter le <span class=\"kw-def\">réflexe gastro-colique</span> (après <span class=\"kw-clinique\">les</span> repas)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Position de défécation</span></td><td>Jambes surélevées, utilisation d'un <strong>marche-pied</strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Pièges « à ne pas dire » (adulte) :</strong> il n'y a <span class=\"kw-alerte\">pas d'intérêt démontré à augmenter les apports hydriques</span>, et l'<span class=\"kw-alerte\">exercice physique n'améliore pas la constipation</span>. Deux affirmations classiquement fausses en QCM.</div>\n      <p><strong>Chez l'enfant (Rang A) — <span class=\"kw-ttt\">RHD</span> spécifiques :</strong></p>\n      <table >\n        <thead><tr><th>Mesure</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Apprentissage de l'exonération</span></td><td><strong>Pédagogie</strong> et <strong>réassurance parentale</strong> — pierre angulaire de la prise en charge</td></tr>\n          <tr><td><span class=\"kw-clinique\">Amélioration des conditions pratiques</span></td><td><strong>Siège de W.-C. adapté</strong> ; <strong>plots sous <span class=\"kw-clinique\">les</span> pieds</strong> (<span class=\"kw-clinique\">poussée</span> abdominale efficace, angle anorectal favorable)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Augmentation des apports en fibres</span></td><td><span class=\"kw-ttt\">Fruits, légumes, céréales complètes</span> — efficacité <span class=\"kw-chiffre\">limitée aux formes bénignes et transitoires</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Arrêt des médicaments constipants</span></td><td>Si possible (<span class=\"kw-ttt\">morphine</span>, <span class=\"kw-ttt\">fer</span>, anticholinergiques…)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Correction des erreurs diététiques</span></td><td>Ex. <span class=\"kw-alerte\">excès d'épaississant</span> du lait infantile, mauvaise reconstitution du lait</td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"283-8","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître et reconnaître les complications de la constipation chronique de l’enfant","contenu":"<p>La <span class=\"kw-clinique\">constipation</span> chronique de l'<strong>enfant</strong> expose à des <strong>complications</strong> qu'il faut savoir reconnaître — elles entretiennent volontiers un <strong>cercle vicieux</strong> : douleur de défécation → rétention volontaire → aggravation de la <span class=\"kw-clinique\">constipation</span>.</p>\n      <table >\n        <thead><tr><th>Complication</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Fissure anale</span></td><td>Provoquée par l'émission de selles dures ; <span class=\"kw-clinique\">douleur à la défécation</span> qui auto-entretient la rétention volontaire</td></tr>\n          <tr><td><span class=\"kw-alerte\">Fécalome / rétention stercorale</span></td><td>Accumulation de matières fécales dures dans le rectum (parfois le côlon) ; diagnostic au <span class=\"kw-clinique\">toucher rectal</span> ; traitement par <span class=\"kw-ttt\">lavement</span> ou <strong>extraction manuelle</strong> ; peut évoluer vers un <span class=\"kw-clinique\">mégarectum</span> fonctionnel ou une <span class=\"kw-alerte\">occlusion</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Encoprésie</span></td><td>Définition : <span class=\"kw-def\">incontinence fécale après l'âge de <span class=\"kw-chiffre\">4 ans</span></span> (âge d'acquisition de la continence) — émissions involontaires dans des situations ou des endroits inappropriés. Mécanisme : <strong>incontinence par regorgement</strong> autour du fécalome, prise à tort pour une vraie <span class=\"kw-clinique\">diarrhée</span> (<span class=\"kw-alerte\">fausse diarrhée</span>). <span class=\"kw-clinique\">Évolution</span> redoutée des <span class=\"kw-clinique\">constipations fonctionnelles</span> sévères et chroniques de l'enfant ; <span class=\"kw-alerte\">retentissement psychosocial</span> majeur</td></tr>\n          <tr><td><span class=\"kw-alerte\">Prolapsus rectal</span></td><td>Favorisé par <span class=\"kw-clinique\">les</span> efforts de <span class=\"kw-clinique\">poussée</span> répétés</td></tr>\n          <tr><td><span class=\"kw-alerte\">Infections urinaires récidivantes</span></td><td>Par compression vésicale ; énurésie volontiers associée</td></tr>\n          <tr><td><span class=\"kw-alerte\">Retentissement psychosocial</span></td><td>Souffrance, retrait social, difficultés scolaires — la <span class=\"kw-clinique\">constipation</span> de l'enfant n'est jamais purement somatique</td></tr>\n        </tbody>\n      </table>\n      <p>Chez l'adulte et le sujet âgé, on retient en plus la <span class=\"kw-alerte\">mélanose colique</span> — « maladie des laxatifs » : p<span class=\"kw-chiffre\">igm</span>entation brunâtre de la muqueuse colique liée à l'usage prolongé de <span class=\"kw-ttt\">laxatifs irritants / stimulants</span>. C'est une complication du <strong>traitement</strong>, et non de la <span class=\"kw-clinique\">constipation</span> elle-même.</p>","frequence":0},{"id":"283-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge de la constipation chronique","contenu":"<p>La prise en charge médicamenteuse repose sur une <strong>escalade thérapeutique</strong>, toujours mise en œuvre après <span class=\"kw-clinique\">les</span> règles hygiénodiététiques.</p>\n      <table >\n        <thead><tr><th>Intention</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1ʳᵉ intention</strong></td><td><span class=\"kw-ttt\">Laxatifs osmotiques</span> ; <span class=\"kw-ttt\">laxatifs de lest</span></td></tr>\n          <tr><td><strong>2ᵉ intention</strong></td><td><span class=\"kw-ttt\">Laxatifs stimulants / irritants</span> — avec prudence, risque de <span class=\"kw-alerte\">mélanose colique</span> ; <span class=\"kw-ttt\">laxatifs lubrifiants</span> ; <span class=\"kw-ttt\">prokinétiques</span> (réservés à l'échec des laxatifs)</td></tr>\n          <tr><td><strong>Voie rectale</strong></td><td><span class=\"kw-ttt\">Suppositoires</span>, <span class=\"kw-ttt\">lavements</span> — action rapide sur la défécation</td></tr>\n          <tr><td><strong>Mesures non médicamenteuses</strong></td><td><span class=\"kw-clinique\">Rééducation anorectale (biofeedback)</span> — utile dans la <span class=\"kw-clinique\">constipation</span> distale ; prise en charge psychologique si nécessaire</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Chirurgie</span></strong> (centres experts)</td><td>Rectocèle / prolapsus après échec du traitement médical et du biofeedback ; inertie colique résistante : colectomie subtotale + anastomose iléorectale, ou irr<span class=\"kw-chiffre\">iga</span>tions antérogrades par mini-stomie</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-clinique\">Les</span> 5 classes de laxatifs et leur mécanisme :</strong></p>\n      <table >\n        <thead><tr><th>Classe</th><th>Mécanisme d'action</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Osmotiques</span></td><td>Effet osmotique : <strong>macrogol</strong> (fixation de molécules d'eau) ; <strong>hydroxyde de magnésium</strong> (osmotique + stimulant) ; <strong>sucres non absorbables</strong> (<span class=\"kw-ttt\">lactulose</span>, lactitol, sorbitol, mannitol)</td></tr>\n          <tr><td><span class=\"kw-ttt\">De lest</span></td><td><strong>Mucilages</strong> : formation d'un ballast retenant l'eau dans la lumière intestinale, augmentation du volume des selles</td></tr>\n          <tr><td><span class=\"kw-ttt\">Émollients / lubrifiants</span></td><td><strong>Huile de paraffine</strong> : lubrification du bol fécal, selles plus molles et plus faciles à évacuer</td></tr>\n          <tr><td><span class=\"kw-ttt\">Stimulants</span></td><td>Anthraquinones, bisacodyl, docusate, picosulfate de sodium, huile de ricin : stimulent la contraction colique ; effets indésirables au long cours — à prescrire avec parcimonie</td></tr>\n          <tr><td><span class=\"kw-ttt\">Voie rectale</span></td><td>Suppositoires, lavements : déclenchent un besoin exonérateur par stimulation de la muqueuse rectale ou dégagement de CO₂</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Focus — <span class=\"kw-clinique\">constipation</span> sous <span class=\"kw-ttt\">opioïdes</span>.</strong> La <span class=\"kw-clinique\">constipation</span> est quasi inéluctable sous <span class=\"kw-ttt\">opioïde fort</span> (stimulation des récepteurs µ du tube digestif → ↓ péristaltisme et ↓ sécrétions digestives).</p>\n      <ul>\n        <li><strong>Traitement préventif :</strong> un <span class=\"kw-ttt\">laxatif</span> est <strong>systématiquement associé</strong> à toute prescription d'opioïde fort, quelles que soient la dose et la durée — laxatif <span class=\"kw-ttt\">osmotique</span> ± <span class=\"kw-ttt\">stimulant</span>, en 1ʳᵉ intention, accompagné des règles hygiénodiététiques.</li>\n        <li><strong>Traitement curatif</strong> (<span class=\"kw-clinique\">constipation</span> installée, <span class=\"kw-chiffre\">après 3 jours sans selle</span>) : éliminer un <span class=\"kw-alerte\">fécalome</span> ou une <span class=\"kw-alerte\">occlusion</span> par l'examen clinique ; augmenter <span class=\"kw-clinique\">les</span> posologies, voire associer les laxatifs (bithérapie osmotique + stimulant) ; lavement rectal si selles au toucher rectal ; en cas d'échec, <span class=\"kw-ttt\">antagonistes morphiniques périphériques</span> — <span class=\"kw-ttt\">naloxégol</span> PO ou <span class=\"kw-ttt\">méthylnaltrexone</span> SC ; en dernier recours, préparation pour invest<span class=\"kw-chiffre\">iga</span>tions coliques ou grand lavement.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-ci\">Contre-indication</span> des antagonistes morphiniques périphériques :</strong> <span class=\"kw-ci\">occlusion digestive connue ou suspectée</span> et <span class=\"kw-ci\">lésion du tractus gastro-intestinal</span>. <span class=\"kw-clinique\">Les</span> écarter impérativement avant toute prescription de naloxégol ou de méthylnaltrexone.</div>\n      <p><strong>Focus — PEC de la <span class=\"kw-clinique\">constipation</span> fonctionnelle de l'enfant.</strong> La stratégie pédiatrique repose sur une <span class=\"kw-def\">approche en 2 temps</span> : <strong>désimpaction</strong> puis <strong>traitement de fond</strong>, encadrée par <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">RHD</span> pédiatriques (cf. objectif Prise en charge — RHD).</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Modalités pédiatriques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1. <span class=\"kw-def\">Désimpaction fécale</span></strong><br><em>(évacuation du fécalome accumulé, primordiale si présent)</em></td>\n            <td><span class=\"kw-ttt\">Lavements hypertoniques</span> sur <span class=\"kw-chiffre\">durée limitée</span> ; <strong>OU</strong> <span class=\"kw-ttt\">laxatifs à dose de désimpaction</span> (PEG haute dose)</td>\n          </tr>\n          <tr>\n            <td><strong>2. <span class=\"kw-def\">Traitement de fond</span></strong><br><em>(prévention de la réaccumulation)</em></td>\n            <td>\n              <strong>1ʳᵉ intention :</strong> <span class=\"kw-ttt\">laxatifs PEG (macrogol)</span> — effet osmotique, <span class=\"kw-clinique\">les</span> plus utilisés chez l'enfant.<br>\n              <strong>Alternative :</strong> <span class=\"kw-ttt\">laxatifs lubrifiants à base de paraffine liquide</span> — ramollissent les selles. <span class=\"kw-alerte\">Piège ⚠️ : risque de pneumonie huileuse</span> en cas de fausse route, notamment si <span class=\"kw-etio\">RGO</span> associé (moins utilisés pour cette raison).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>3. Prise en charge psychologique</strong></td>\n            <td><span class=\"kw-clinique\">Indispensable en cas d'<span class=\"kw-alerte\">encoprésie</span></span> ; utile si cause psychologique à la rétention, conséquences psychosociales du trouble, ou bénéfice secondaire recherché</td>\n          </tr>\n          <tr>\n            <td><strong>4. <span class=\"kw-def\">Suivi</span> / <span class=\"kw-def\">pronostic</span></strong></td>\n            <td><span class=\"kw-clinique\">Constipation</span> fonctionnelle peu sévère : <span class=\"kw-clinique\">évolution</span> favorable mais <span class=\"kw-clinique\">récidives fréquentes</span>. Constipation sévère avec <span class=\"kw-alerte\">encoprésie</span> : <span class=\"kw-def\">pronostic</span> plus réservé, prise en charge à poursuivre parfois <span class=\"kw-chiffre\">plusieurs mois, voire années</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 135 — <span class=\"kw-ttt\">Antalgique</span> · 139 — Soins palliatifs - repères cliniques - organisation hospitalière et ambulatoire</em></p>","frequence":0}],"astuces":[],"strategie":{"hospit":"<p><strong>Ambulatoire :</strong> prise en charge quasi exclusivement <span class=\"kw-def\">ambulatoire</span> — l’<span class=\"kw-clinique\">urgence est quasi nulle</span> dans la <span class=\"kw-clinique\">constipation</span> chronique.<br><strong>Avis / exploration :</strong> devant un <span class=\"kw-alerte\">signe d’alarme</span>, un <span class=\"kw-chiffre\">âge &gt; 50 ans</span> ou un <span class=\"kw-etio\">ATCD familial de cancer colique</span> → <span class=\"kw-imagerie\">coloscopie</span> programmée.<br><strong><span class=\"kw-alerte\">Urgence</span> hospitalière :</strong> <span class=\"kw-clinique\">constipation aiguë</span> faisant évoquer un <span class=\"kw-alerte\">syndrome occlusif</span> (urgence diagnostique, surtout chez l’enfant) ou un <span class=\"kw-alerte\">fécalome compliqué</span>.<br><strong>Centre expert :</strong> <span class=\"kw-ttt\">chirurgie</span> de l’inertie colique ou des troubles de la statique pelvienne ; <span class=\"kw-etio\">maladie de Hirschsprung</span> → <span class=\"kw-ttt\">chirurgie</span> pédiatrique spécialisée.</p>","redflags":"<ul><li><span class=\"kw-alerte\">AEG</span>, <span class=\"kw-clinique\">amaigrissement</span> inexpliqué</li><li><span class=\"kw-alerte\">Rectorragies</span> ou <span class=\"kw-clinique\">méléna</span> ; <span class=\"kw-bio\">anémie</span> ou <span class=\"kw-bio\">syndrome inflammatoire</span></li><li><span class=\"kw-clinique\">Syndrome rectal</span> (épreintes, ténesme, faux besoins) ; <span class=\"kw-clinique\">masse abdominale ou rectale</span></li><li><span class=\"kw-clinique\">Modification récente et inexpliquée du transit</span> ou <span class=\"kw-clinique\">douleurs nocturnes insomniantes</span></li><li><span class=\"kw-clinique\">Constipation sévère résistante</span> au traitement bien conduit ou s’aggravant sans cause évidente</li><li><span class=\"kw-clinique\">Constipation aiguë</span> → évoquer un <span class=\"kw-alerte\">syndrome occlusif</span> (<span class=\"kw-alerte\">urgence</span> diagnostique)</li><li>Enfant : <span class=\"kw-alerte\">retard d’émission du méconium &gt; 48 h</span>, <span class=\"kw-alerte\">cassure staturo-pondérale</span>, <span class=\"kw-alerte\">épisodes subocclusifs</span> / <span class=\"kw-clinique\">vomissements</span>, <span class=\"kw-clinique\">anomalies de la marge anale, du périnée ou de la région sacrée</span></li></ul>","principes":"<p><strong>Règle d’or :</strong> <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">règles hygiénodiététiques</span> sont le socle (<span class=\"kw-chiffre\">1ʳᵉ ligne</span>) ; escalade médicamenteuse ensuite. <span class=\"kw-alerte\">Aucun examen complémentaire</span> n’est systématique en l’absence de signe d’alarme.</p><p><strong>Escalade des laxatifs <span class=\"q\">— 5 classes</span></strong></p><ul><li><span class=\"kw-chiffre\">1ʳᵉ intention</span> : <span class=\"kw-ttt\">laxatifs osmotiques</span> (macrogol) · <span class=\"kw-ttt\">laxatifs de lest</span> (mucilages)</li><li><span class=\"kw-chiffre\">2ᵉ intention</span> : <span class=\"kw-ttt\">laxatifs stimulants</span> (avec prudence : risque de <span class=\"kw-alerte\">mélanose colique</span>) · <span class=\"kw-ttt\">lubrifiants</span> (paraffine) · <span class=\"kw-ttt\">prokinétiques</span></li><li>Voie rectale : <span class=\"kw-ttt\">suppositoires</span>, <span class=\"kw-ttt\">lavements</span> — action rapide</li></ul><p><strong><span class=\"kw-clinique\">Constipation</span> sous <span class=\"kw-ttt\">opioïdes</span></strong></p><p><span class=\"kw-ci\">CI des antagonistes morphiniques : occlusion connue/suspectée ou lésion du tractus gastro-intestinal</span></p><ul><li>Préventif : <span class=\"kw-ttt\">laxatif systématique</span> (osmotique ± stimulant) à toute prescription d’<span class=\"kw-ttt\">opioïde fort</span></li><li>Curatif <span class=\"kw-chiffre\">après 3 jours sans selle</span> : éliminer un <span class=\"kw-alerte\">fécalome</span> / une <span class=\"kw-alerte\">occlusion</span>, bithérapie laxative, lavement</li><li>Échec : <span class=\"kw-ttt\">antagonistes morphiniques périphériques</span> (<span class=\"kw-ttt\">naloxégol</span> PO, <span class=\"kw-ttt\">méthylnaltrexone</span> SC)</li></ul><p><strong><span class=\"kw-clinique\">Constipation</span> fonctionnelle de l’enfant</strong></p><ul><li><span class=\"kw-def\">Désimpaction</span> du fécalome : <span class=\"kw-ttt\">lavements hypertoniques</span> (durée limitée) ou <span class=\"kw-ttt\">PEG à dose de désimpaction</span></li><li>Traitement de fond : <span class=\"kw-ttt\">PEG (macrogol)</span> en 1ʳᵉ intention ; <span class=\"kw-ttt\">paraffine</span> en alternative (<span class=\"kw-alerte\">risque de pneumonie huileuse</span> si fausse route / <span class=\"kw-clinique\">RGO</span>)</li><li><span class=\"kw-ttt\">PEC psychologique</span> indispensable si <span class=\"kw-alerte\">encoprésie</span></li></ul><p><strong>Fécalome / rétention stercorale</strong></p><ul><li>Diagnostic au <span class=\"kw-clinique\">toucher rectal</span></li><li>Traitement : <span class=\"kw-ttt\">lavement</span> ou <strong>extraction manuelle</strong></li></ul>","suivi":"<p><strong>Efficacité &amp; observance :</strong> réévaluer la réponse au traitement et l’adhésion aux <span class=\"kw-def\">RHD</span> ; adapter l’escalade laxative.<br><strong>Complications à dépister :</strong> <span class=\"kw-alerte\">fécalome</span>, <span class=\"kw-alerte\">fissure anale</span>, <span class=\"kw-alerte\">prolapsus rectal</span>, <span class=\"kw-alerte\">encoprésie</span> (enfant), <span class=\"kw-alerte\">mélanose colique</span> (abus de <span class=\"kw-ttt\">laxatifs irritants</span>).<br><strong><span class=\"kw-def\">Pronostic</span> (enfant) :</strong> forme fonctionnelle peu sévère → <span class=\"kw-clinique\">évolution</span> souvent favorable mais <span class=\"kw-clinique\">récidives fréquentes</span> ; forme sévère avec <span class=\"kw-alerte\">encoprésie</span> → pronostic plus réservé, PEC parfois prolongée <span class=\"kw-chiffre\">plusieurs mois, voire années</span>.<br><strong>Imagerie de <span class=\"kw-def\">suivi</span> :</strong> l’<span class=\"kw-imagerie\">ASP</span> n’a <span class=\"kw-alerte\">aucune indication</span> dans le suivi d’une <span class=\"kw-clinique\">constipation</span> fonctionnelle.</p>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/gastroenterologie-nutrition-chirurgie-abdomino-pelvienne/constipation","label":"Pedia-univ — Constipation"},{"href":"https://fr.wikipedia.org/wiki/%C3%89chelle_de_Bristol","label":"Échelle de Bristol"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Constipation chronique — Éliminer une cause secondaire / organique avant de retenir une constipation fonctionnelle","detail":"<h4>CAT — <span class=\"kw-clinique\">constipation</span> chronique — Démarche diagnostique : fonctionnelle ou secondaire ? (adulte & enfant)</h4>","branches":[{"to":"t-organique","label":"Signe d’alarme, âge > 50 ans, ou ATCD familial de cancer colique","color":"red"},{"to":"q-enfant","label":"Pas de signe d’alarme — enfant : début néonatal ou retard de méconium > 48 h ?","color":"amber"}]},{"id":"t-organique","kind":"terminal","label":"Constipation secondaire (organique) à explorer","color":"red","detail":"<h4>Signes d’alarme</h4><ul><li><span class=\"kw-alerte\">AEG</span>, <span class=\"kw-clinique\">amaigrissement</span>, <span class=\"kw-alerte\">rectorragies</span>, <span class=\"kw-clinique\">méléna</span></li><li><span class=\"kw-clinique\">Syndrome rectal</span>, <span class=\"kw-clinique\">masse abdominale/rectale</span>, <span class=\"kw-clinique\">modification récente du transit</span></li><li><span class=\"kw-bio\">Anémie</span>, <span class=\"kw-bio\">syndrome inflammatoire</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">Coloscopie</span> sous AG (âge <span class=\"kw-chiffre\">&gt; 50 ans</span>, signe d’alarme, <span class=\"kw-def\">dépistage</span> du cancer colorectal) ; <span class=\"kw-imagerie\">coloscanner</span> si CI ou <span class=\"kw-imagerie\">coloscopie</span> incomplète</li><li><span class=\"kw-bio\">Bilan</span> orienté : <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">créatininémie</span>, <span class=\"kw-bio\">glycémie</span>, <span class=\"kw-bio\">calcémie</span>, <span class=\"kw-bio\">TSH</span></li></ul><h4>Causes principales</h4><ul><li><span class=\"kw-etio\">Médicaments</span> (<span class=\"kw-ttt\">opiacés</span> +++), <span class=\"kw-etio\">obstruction mécanique</span> (cancer colorectal, sténose, compression)</li><li><span class=\"kw-etio\">Métaboliques</span> (hypercalcémie, hypokaliémie, hypothyroïdie, <span class=\"kw-etio\">diabète</span>), causes <span class=\"kw-etio\">neurologiques</span></li></ul><h4>Renvoi</h4><ul><li>Item 301 (Tumeur côlon-rectum) · Item 354 (Syndrome occlusif)</li></ul>"},{"id":"q-enfant","kind":"decision","label":"Contexte pédiatrique évocateur d’une cause congénitale ? — Début néonatal · retard d’émission du méconium > 48 h · cassure staturo-pondérale · échec du traitement symptomatique","branches":[{"to":"t-hirschsprung","label":"Oui — constipation néonatale / méconium retardé","color":"amber"},{"to":"q-mecanisme","label":"Non — constipation fonctionnelle probable","color":"green"}]},{"id":"t-hirschsprung","kind":"terminal","label":"Maladie de Hirschsprung à éliminer","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-alerte\">Retard d’émission du méconium &gt; 24-48 h</span>, <span class=\"kw-clinique\">constipation dès la naissance</span></li><li>TR : <span class=\"kw-clinique\">ampoule rectale vide</span>, <span class=\"kw-clinique\">hypertonie sphinctérienne</span>, <span class=\"kw-clinique\">débâcle de selles fétides au retrait du doigt</span></li><li>Association à la <span class=\"kw-etio\">trisomie 21</span> ; <span class=\"kw-def\">prévalence</span> <span class=\"kw-chiffre\">1 cas / 5 000</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">Manométrie anorectale</span> : <span class=\"kw-def\">absence de réflexe recto-anal inhibiteur</span></li><li><span class=\"kw-imagerie\">Lavement opaque</span> : disparité de calibre avec stagnation sus-jacente</li><li><span class=\"kw-bio\">Biopsies rectales</span> = confirmation : <span class=\"kw-def\">aganglionose avec hyperplasie schwannienne</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Chirurgical</span> : <span class=\"kw-ttt\">exérèse</span> du segment apéristaltique</li></ul>"},{"id":"q-mecanisme","kind":"decision","label":"Après échec des RHD : mécanisme de la constipation fonctionnelle ? — Orientation transit vs distale (clinique + temps de transit ± manométrie anorectale)","branches":[{"to":"t-transit","label":"Constipation de transit (transit ralenti, manométrie normale)","color":"green"},{"to":"t-distale","label":"Constipation distale / dyschésie (trouble de l’évacuation)","color":"blue"}]},{"id":"t-transit","kind":"terminal","label":"Constipation fonctionnelle de transit","color":"green","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Nombre de selles diminué</span>, selles dures ; <span class=\"kw-imagerie\">temps de transit augmenté</span>, <span class=\"kw-clinique\">manométrie anorectale normale</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-def\">RHD</span> : fibres <span class=\"kw-chiffre\">~25 g/j</span>, présentation régulière aux toilettes, position de défécation (marche-pied)</li><li><span class=\"kw-ttt\">Laxatifs osmotiques</span> + <span class=\"kw-ttt\">de lest</span> en 1ʳᵉ intention ; enfant : <span class=\"kw-ttt\">PEG (macrogol)</span> après désimpaction</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-def\">Réévaluation</span> de l’efficacité ; <span class=\"kw-alerte\">récidives fréquentes</span></li></ul>"},{"id":"t-distale","kind":"terminal","label":"Constipation fonctionnelle distale (dyschésie)","color":"blue","detail":"<h4>Mécanisme</h4><ul><li><span class=\"kw-def\">Dyssynergie anorectale</span> (défaut d’ouverture du canal anal à la <span class=\"kw-clinique\">poussée</span>)</li><li><span class=\"kw-def\">Troubles de la statique pelvienne</span> (rectocèle, procidence) ; <span class=\"kw-def\">hyposensibilité rectale</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">Manométrie anorectale</span> ; <span class=\"kw-imagerie\">défécographie</span> / <span class=\"kw-imagerie\">déféco-IRM</span> si <span class=\"kw-ttt\">chirurgie</span> envisagée</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Rééducation anorectale (biofeedback)</span> en 1ʳᵉ intention</li><li><span class=\"kw-ttt\">Chirurgie</span> (centre expert) : rectocèle/prolapsus après échec du biofeedback ; inertie colique → colectomie subtotale + anastomose iléorectale</li></ul>"}]},"cards":[{"i":"1ae9405e8d4b","n":283,"o":"283-2","u":"Définition","t":"Connaître la définition de la constipation chronique","q":"Comment l'échelle de Bristol permet-elle d'apprécier une constipation ?","a":"<p>L'échelle de Bristol est un outil visuel qui catégorise la forme et la consistance des selles. Un score de <strong>Bristol 1</strong> (selles dures, séparées, comme des noisettes) ou <strong>Bristol 2</strong> (selles en forme de saucisse, grumeleuses) est caractéristique de la constipation.</p>"},{"i":"772ee12e57c0","n":283,"o":"283-2","u":"Définition","t":"Connaître la définition de la constipation chronique","q":"Quels sont les critères diagnostiques de la constipation chronique chez l'enfant après 4 ans, selon Rome IV ?","a":"<p>Chez l'enfant de <strong>plus de 4 ans</strong> (avec au moins <strong>2 critères présents au moins une fois par semaine depuis 1 mois</strong>, et en l'absence de SII) les critères de Rome IV incluent :</p><ul><li>Moins de <strong>2 selles par semaine</strong>.</li><li>Au moins <strong>1 épisode d'incontinence</strong> par semaine.</li><li>Posture de rétention ou rétention délibérée des selles.</li><li>Exonération douloureuse ou difficile.</li><li>Fécalome au toucher rectal.</li><li>Selles de gros calibre.</li></ul>"},{"i":"9854918b706a","n":283,"o":"283-2","u":"Définition","t":"Connaître la définition de la constipation chronique","q":"Comment définir la constipation chronique chez l'adulte ?","a":"<p>Chez l'adulte, la constipation se définit par au moins l'un des deux critères suivants :</p><ul><li>Moins de <strong>3 selles par semaine</strong>.</li><li>Une <strong>difficulté d'exonération (dyschésie)</strong>, qui peut inclure des efforts de poussée exagérés, une sensation de gêne, une évacuation incomplète, un temps d'exonération prolongé, ou la nécessité de manœuvres digitales.</li></ul><p>Ces manifestations doivent être présentes pendant plus de <strong>6 mois</strong> pour être qualifiées de chroniques, et doivent impérativement correspondre à une plainte du patient.</p>"},{"i":"e15c1e88b041","n":283,"o":"283-2","u":"Définition","t":"Connaître la définition de la constipation chronique","q":"Quels sont les critères diagnostiques de la constipation chronique chez l'enfant avant 4 ans, selon Rome IV ?","a":"<p>Chez l'enfant de <strong>moins de 4 ans</strong> (avec au moins <strong>2 critères présents depuis 1 mois</strong>) les critères de Rome IV incluent :</p><ul><li>Moins de <strong>2 selles par semaine</strong>.</li><li>Rétention fécale excessive.</li><li>Exonération douloureuse ou difficile.</li><li>Selles de gros calibre.</li><li>Fécalome au toucher rectal.</li><li>Après l'acquisition de la propreté : <strong>au moins 1 épisode d'incontinence</strong> par semaine et/ou des selles de gros calibre pouvant obstruer les toilettes.</li></ul>"},{"i":"19deea85225f","n":283,"o":"283-5","u":"Diagnostic positif","t":"Connaître les caractéristiques cliniques et les éléments de diagnostic différentiel","q":"Quels sont les critères diagnostiques cliniques de la constipation chez l'adulte et l'enfant ?","a":"<p>La constipation est définie par :</p><ul><li>Une <strong>fréquence de selles inférieure à 3 par semaine</strong></li><li>Ou une <strong>dyschésie</strong> (difficulté à évacuer les selles).</li></ul><p>Ces critères s'associent à une plainte du patient.</p>"},{"i":"4b6f150e85e5","n":283,"o":"283-5","u":"Diagnostic positif","t":"Connaître les caractéristiques cliniques et les éléments de diagnostic différentiel","q":"Quel est l'intérêt du toucher rectal chez l'enfant devant une suspicion de constipation ?","a":"<p>Chez l'enfant, le toucher rectal est un temps essentiel de l’examen clinique. Il permet de :</p><ul><li>Rechercher un <strong>fécalome</strong>.</li><li>Apprécier le <strong>tonus sphinctérien</strong>.</li><li>Évaluer la <strong>vacuité de l'ampoule rectale</strong>.</li></ul><p>Ces éléments peuvent orienter vers une <strong>cause organique</strong>, notamment la maladie de <strong>Hirschsprung</strong>.</p>"},{"i":"6018256a61ea","n":283,"o":"283-5","u":"Diagnostic positif","t":"Connaître les caractéristiques cliniques et les éléments de diagnostic différentiel","q":"Quels sont les signes cliniques retrouvés à l'examen physique en cas de constipation ?","a":"<p>L'examen physique peut retrouver :</p><ul><li>Une <strong>sensibilité de la fosse iliaque gauche</strong>, en regard du côlon gauche et du sigmoïde.</li><li>Un <strong>météorisme abdominal</strong>.</li><li>L'<strong>échelle de Bristol score 1 ou 2</strong> objective la consistance des selles.</li></ul>"},{"i":"dec695431462","n":283,"o":"283-5","u":"Diagnostic positif","t":"Connaître les caractéristiques cliniques et les éléments de diagnostic différentiel","q":"Comment différencier une fausse diarrhée d'une diarrhée chronique authentique ou d'un syndrome de l'intestin irritable avec constipation ?","a":"<ul><li>La <strong>fausse diarrhée</strong> correspond à l'émission de selles liquides précédant ou suivant une période de rétention, et est en réalité une constipation sous-jacente.</li><li>Le <strong>syndrome de l'intestin irritable (SII) avec constipation</strong> est caractérisé par une constipation associée à une douleur abdominale au premier plan (due à une hyperactivité segmentaire sigmoïdienne).</li><li>La <strong>diarrhée chronique vraie</strong> est définie par des selles authentiquement trop fréquentes et/ou trop liquides, sans période de rétention, ce qui est l'opposé de la constipation.</li></ul>"},{"i":"1bdb24a48bd4","n":283,"o":"283-7","u":"Prise en charge","t":"Connaître les règles hygiénodiététiques","q":"Quelle est la place des règles hygiénodiététiques dans la prise en charge de la constipation idiopathique chez l'adulte et l'enfant ?","a":"<p>Les règles hygiénodiététiques constituent le <strong>socle de la prise en charge</strong> de la constipation idiopathique, en <strong>première ligne</strong> et avant tout traitement médicamenteux.</p>"},{"i":"4455354c9ba7","n":283,"o":"283-7","u":"Prise en charge","t":"Connaître les règles hygiénodiététiques","q":"Quelles sont les principales règles hygiénodiététiques recommandées chez l'adulte en cas de constipation idiopathique ?","a":"<ul><li>Un <strong>régime enrichi en fibres</strong> (environ <strong>25 g/jour</strong>) : fruits, légumes, céréales.</li><li>La consommation d'<strong>eaux riches en magnésium</strong> peut être recommandée.</li><li>Présentation régulière aux toilettes pour <strong>exploiter le réflexe gastro-colique</strong> (après les repas).</li><li>Une <strong>position de défécation adaptée</strong> (jambes surélevées, utilisation d'un marche-pied).</li></ul>"},{"i":"50ab837decde","n":283,"o":"283-7","u":"Prise en charge","t":"Connaître les règles hygiénodiététiques","q":"Concernant les règles hygiénodiététiques chez l'adulte, quels sont les deux pièges classiques à éviter dans la prise en charge de la constipation idiopathique ?","a":"<ul><li>Il n'y a pas d'<strong>intérêt démontré à augmenter les apports hydriques</strong>.</li><li>L'<strong>exercice physique n'améliore pas la constipation</strong>.</li></ul>"},{"i":"f2a995258159","n":283,"o":"283-7","u":"Prise en charge","t":"Connaître les règles hygiénodiététiques","q":"Quelles sont les règles hygiénodiététiques spécifiques et la pierre angulaire de la prise en charge de la constipation idiopathique chez l'enfant ?","a":"<ul><li>L'<strong>apprentissage de l'exonération</strong> par la pédagogie et la réassurance parentale est la <strong>pierre angulaire</strong> de la prise en charge.</li><li>L'amélioration des conditions pratiques : siège de W.-C. adapté, plots sous les pieds pour une poussée abdominale efficace et un angle anorectal favorable.</li><li>L'augmentation des apports en fibres (fruits, légumes, céréales complètes) est d'efficacité limitée aux formes bénignes et transitoires.</li><li>L'arrêt des médicaments constipants si possible (<strong>morphine</strong>, <strong>fer</strong>, <strong>anticholinergiques</strong>).</li><li>La correction des erreurs diététiques (ex: excès d'épaississant du lait infantile, mauvaise reconstitution du lait).</li></ul>"}]};